style:
.tw-zhusha.resume-paper {
  color: #2b2424;
}

.tw-zhusha.resume-paper .paper-header {
  position: relative;
  align-items: flex-start;
  gap: 8mm;
  margin: 0 0 5mm;
  padding: 0 0 4mm;
  border: none;
  border-bottom: 1.5px solid #c0262d;
  text-align: left;
}

.tw-zhusha.resume-paper .paper-header::before {
  content: "";
  position: absolute;
  top: calc(var(--paper-mt, 15mm) * -1);
  left: calc(var(--paper-ml, 15mm) * -1);
  right: calc(var(--paper-mr, 15mm) * -1);
  height: 2.4mm;
  background: #c0262d;
  print-color-adjust: exact;
}

.tw-zhusha.resume-paper .paper-name {
  color: #231d1d;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.15);
  letter-spacing: 0.1em;
}

.tw-zhusha.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: #7c6d6d;
}

.tw-zhusha.resume-paper .paper-role {
  margin-top: 1.4mm;
  color: #c0262d;
  font-weight: 700;
  letter-spacing: 0.04em;
}

.tw-zhusha.resume-paper .paper-role::before {
  content: "求职意向：";
  color: #7c2a2e;
  font-weight: 400;
  font-size: calc(var(--paper-base-size) * 0.94);
}

.tw-zhusha.resume-paper .paper-contacts--labeled {
  display: flex;
  flex-wrap: wrap;
  gap: 1.2mm 6mm;
  margin-top: 2.8mm;
  color: #3c3232;
  font-size: calc(var(--paper-base-size) * 0.88);
}

.tw-zhusha.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-zhusha.resume-paper .paper-contact__label {
  color: #8c7a7a;
}

.tw-zhusha.resume-paper .paper-photo {
  width: 26mm;
  height: 34mm;
  padding: 1.6mm;
  print-color-adjust: exact;
}

.tw-zhusha.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background-color: #fbf1f1;
  background-clip: border-box;
  color: #c0262d;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 600;
}

.tw-zhusha.resume-paper .paper-section .paper-section__title {
  display: block;
  margin-bottom: 2.6mm;
  padding: 0 0 1.2mm;
  border-bottom: 1.5px dotted #c0262d;
  color: #221d1d;
  font-size: calc(var(--paper-base-size) * 1.12);
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: none;
}

.tw-zhusha.resume-paper .paper-section .paper-section__icon {
  display: none;
}

.tw-zhusha.resume-paper .paper-section .paper-section__title::after {
  content: none;
}

.tw-zhusha.resume-paper .paper-section .paper-section__body {
  color: #332b2b;
}

.tw-zhusha.resume-paper .paper-section .paper-item-title {
  color: #1c1c1c;
}

.tw-zhusha.resume-paper .paper-section .paper-item-period {
  color: #6f5a5a;
  font-weight: 600;
}

.tw-zhusha.resume-paper .paper-section .paper-item-sub {
  color: #4a3f3f;
}

.tw-zhusha.resume-paper .paper-section .paper-note__tag {
  color: #c0262d;
}

.tw-zhusha.resume-paper .paper-section .paper-item-tag {
  background: #fdf2f2;
  color: #c0262d;
  border: 0.2mm solid #ecc9ca;
  print-color-adjust: exact;
}

.tw-zhusha.resume-paper .paper-section .paper-rich ul {
  margin: 0.6mm 0 0;
  padding-left: 0;
  list-style: none;
  counter-reset: zhusha-li;
}

.tw-zhusha.resume-paper .paper-section .paper-rich ul > li {
  position: relative;
  margin: 0.4mm 0;
  padding-left: 5mm;
  counter-increment: zhusha-li;
}

.tw-zhusha.resume-paper .paper-section .paper-rich ul > li::before {
  content: counter(zhusha-li) "、";
  position: absolute;
  left: 0;
  color: #a32429;
  font-weight: 600;
}

.tw-zhusha.resume-paper .paper-section .paper-skill {
  border-bottom-color: #f0e4e4;
}

.tw-zhusha.resume-paper .paper-section .paper-skill__level {
  color: #c0262d;
}

.tw-zhusha.resume-paper .paper-footer {
  border-top: 1px solid #eadede;
  color: #7d6f6f;
}

/* 显式选择的列表样式接管模板默认圆点装饰，避免 data-list 被模板 ul/li 规则盖掉。 */
.tw-zhusha.resume-paper .paper-rich ul[data-list],
.tw-zhusha.resume-paper .paper-rich ol[data-list] {
  margin: 0.5mm 0 0;
  padding-left: 1.2em;
}
.tw-zhusha.resume-paper .paper-rich ul[data-list] > li,
.tw-zhusha.resume-paper .paper-rich ol[data-list] > li {
  padding-left: 0;
  position: relative;
}
.tw-zhusha.resume-paper .paper-rich ul[data-list] > li::before,
.tw-zhusha.resume-paper .paper-rich ol[data-list] > li::before {
  content: none;
  width: auto;
  height: auto;
  border-radius: 0;
  background: none;
  border: 0;
  box-shadow: none;
  left: auto;
  right: auto;
  top: auto;
  margin: 0;
  padding: 0;
}
.tw-zhusha.resume-paper .paper-rich ul[data-list="disc"] { list-style-type: disc; }
.tw-zhusha.resume-paper .paper-rich ul[data-list="circle"] { list-style-type: circle; }
.tw-zhusha.resume-paper .paper-rich ul[data-list="square"] { list-style-type: square; }
.tw-zhusha.resume-paper .paper-rich ul[data-list="square-open"] { list-style-type: "□   "; }
.tw-zhusha.resume-paper .paper-rich ul[data-list="square-open"] > li::marker { font-size: 0.62em; }
.tw-zhusha.resume-paper .paper-rich ul[data-list="diamond"] { list-style-type: "◆   "; }
.tw-zhusha.resume-paper .paper-rich ul[data-list="diamond-open"] { list-style-type: "◇   "; }
.tw-zhusha.resume-paper .paper-rich ul[data-list="diamond"] > li::marker,
.tw-zhusha.resume-paper .paper-rich ul[data-list="diamond-open"] > li::marker { font-size: 0.62em; }
.tw-zhusha.resume-paper .paper-rich ul[data-list="triangle"] { list-style-type: "▸   "; }
.tw-zhusha.resume-paper .paper-rich ul[data-list="check"] { list-style-type: "✓   "; }
.tw-zhusha.resume-paper .paper-rich ul[data-list="check"] > li::marker { font-size: 0.75em; }
.tw-zhusha.resume-paper .paper-rich ol[data-list="decimal"] { list-style-type: decimal; }
.tw-zhusha.resume-paper .paper-rich ol[data-list="cjk"] { list-style-type: miniwho-cjk; }
.tw-zhusha.resume-paper .paper-rich ol[data-list="roman-upper"] { list-style-type: upper-roman; }
.tw-zhusha.resume-paper .paper-rich ol[data-list="roman-lower"] { list-style-type: lower-roman; }
.tw-zhusha.resume-paper .paper-rich ol[data-list="alpha-upper"] { list-style-type: upper-alpha; }
.tw-zhusha.resume-paper .paper-rich ol[data-list="alpha-lower"] { list-style-type: lower-alpha; }
.tw-zhusha.resume-paper .paper-rich ol[data-list="paren"] { padding-left: 1.2em; list-style: none; counter-reset: paren-item; }
.tw-zhusha.resume-paper .paper-rich ol[data-list="paren"] > li { position: relative; counter-increment: paren-item; }
.tw-zhusha.resume-paper .paper-rich ol[data-list="paren"] > li::before {
  content: "（" counter(paren-item) "）";
  position: absolute;
  right: calc(100% + 0.08em);
  top: 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  font-size: 0.62em;
  line-height: 1.7;
  white-space: nowrap;
}
.tw-zhusha.resume-paper .paper-rich ol[data-list="paren-right"] { padding-left: 1.2em; list-style: none; counter-reset: paren-right-item; }
.tw-zhusha.resume-paper .paper-rich ol[data-list="paren-right"] > li { position: relative; counter-increment: paren-right-item; }
.tw-zhusha.resume-paper .paper-rich ol[data-list="paren-right"] > li::before {
  content: counter(paren-right-item) ")";
  position: absolute;
  right: calc(100% + 0.12em);
  top: 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
